record.field:
label = env.ref('account_offering.menu_account_offering').name
tag = env.ref('account_offering.account_tag_default_offering')
accounts = env['account.account'].search([('tag_ids', 'in', tag.ids)])
debit_accounts = [account for account in accounts if account.internal_group in ('asset', 'expense')]
credit_accounts = [account for account in accounts if account.internal_group not in ('asset', 'expense')]
if not debit_accounts or not credit_accounts:
    raise UserError(str(env['ir.qweb']._render('account_offering.error_missing_default_accounts')).strip())

debit_extra = max(0, len(credit_accounts) - len(debit_accounts))
credit_extra = max(0, len(debit_accounts) - len(credit_accounts))
today = datetime.datetime.now(timezone(env.user.tz or 'UTC')).date()
move = env['account.move'].create({
    'journal_id': env.ref('account_offering.journal_offering').id,
    'ref': label,
    'date': today,
    'line_ids': [
        Command.create({
            'account_id': account.id,
            'debit': 1.0 + debit_extra if account == debit_accounts[-1] else 1.0,
        })
        for account in debit_accounts
    ] + [
        Command.create({
            'account_id': account.id,
            'credit': 1.0 + credit_extra if account == credit_accounts[-1] else 1.0,
        })
        for account in credit_accounts
    ],
})

action = {
    'type': 'ir.actions.act_window',
    'name': label,
    'res_model': 'account.move',
    'views': [[env.ref('account_offering.view_account_move_form_offering').id, 'form']],
    'res_id': move.id,
    'target': 'current',
}
